  "update.useDefault": "Prati zadano",
  "update.afterBackupOrphans":
    "Docker zadržava sliku na kojoj je spremnik prije radio, sada bez oznake, a Unraid je prikazuje kao sliku siroče. To je normalan ostatak uspješnog ažuriranja, a ne znak neuspjelog, i upravo je to ono što treba za brzo vraćanje na prethodnu sliku. Ako je ne želite zadržati, prekidač „Ukloni staru sliku nakon ažuriranja” pod Postavke, Raspored, Ažuriranja nakon sigurnosne kopije briše zamijenjenu sliku odmah nakon ažuriranja.",
