  "breakdown.title": "Veličina po mapi",
  "breakdown.hint": "Što zauzima prostor u najnovijoj sigurnosnoj kopiji, najveće prvo, i koliko je toga posljednja kopija donijela kao novo ili promijenjeno. Promijenjena datoteka računa se cijelom svojom veličinom jer restic ne kaže koliko se u njoj promijenilo. Veličine su veličine datoteka prije uklanjanja duplikata i sažimanja. BombVault ih čita iz indeksa repozitorija bez čitanja datoteka i ažurira ih nakon svake kopije.",
