  // Settings
  "settings.title": "Postavke",
  "settings.encryptionPasswordWhere":
    "Tu lozinku nikada ne upisujete: BombVault je pri svakom pozivu izvodi iz APP_KEY. Sama vrijednost nalazi se u vašem kompletu za oporavak kao izvedena restic lozinka i upravo je ona potrebna za ručno pokretanje restic nad spremištem.",
  "settings.encryptionHint": "Šifriranje se za repozitorij utvrđuje pri njegovu stvaranju, pa ova postavka odlučuje samo o novom repozitoriju. Za već postojeći BombVault način očitava s samog repozitorija. Pogledajte stranicu Vraćanje. Promjena nasuprot postojećem repozitoriju samo sprječava restic da ga otvori.",

  // Encryption-key recovery kit
  "recovery.title": "Komplet za oporavak",
  "recovery.download": "Preuzmi komplet za oporavak",
  "recovery.why": "Kad je enkripcija uključena, vaš APP_KEY je glavna tajna za svaku sigurnosnu kopiju. Preuzmite komplet za oporavak (ključ, izvedenu restic lozinku, lokacije repozitorija i korake za ručno vraćanje) kako biste mogli vratiti podatke čak i bez pokrenutog BombVault kontejnera. Spremite ga izvanmrežno i na sigurnom mjestu.",
  "recovery.nagTitle": "Spremite svoj komplet za oporavak",
  "recovery.nagBody": "Bez kompleta za oporavak nakon potpunog gubitka ne možete doći do svojih enkriptiranih sigurnosnih kopija.",
  "recovery.stored": "Sigurno sam ga pohranio",

