  "settings.compression": "Kompresija",
  "settings.compressionInfo": "Kako restic pakira nove podatke u ovaj repozitorij. Automatski je zadana postavka restica i odgovara većini podataka. Najveća štedi više prostora i troši više procesorskog vremena pri sigurnosnim kopijama i kopiranju. Isključeno sprema podatke bez kompresije, što pomaže kad su već komprimirani, poput videa ili fotografija. Repozitorij u starom formatu verzije 1 ne može komprimirati i zanemaruje ovu postavku.",
