  "settings.primaryRemote.hint": "Ova putanja sigurnosne kopije je udaljeni restic repozitorij. On je primarna kopija, a ne replika. Ovdje postavite ograničenja propusnosti, zaštitu samo-dodavanja i alarm proračuna rasta, istu zaštitu koju dobiva kopija izvan lokacije.",
  "settings.primaryRemote.budgetHint": "Alarm kad ovaj repozitorij premaši proračun bajtova (0 = isključeno).",
  "settings.offsiteHint": "Nakon svake uspješne lokalne sigurnosne kopije, replicira se i u drugi repozitorij pomoću restic copy. Unesite udaljenu lokaciju (rest:http://host:8000/repo, s3:…) ili lokalnu podputanju; ostavite prazno za onemogućavanje. Lokalna sigurnosna kopija ostaje primarna.",
