  "offsite.rcloneWarning": "rclone serve restic --append-only ima otvorenu grešku ponovnog pokušaja s izvorom koja može izgubiti dodane podatke. Za nepromjenjivu pohranu izvan lokacije preporučuje se rest-server.",
  "offsite.s3Unverified": "Napomena: samo-dodavanje na S3 ne može se automatski provjeriti. Ručno postavite verzioniranje bucketa + zabranu brisanja; kartica rezultata i dalje označava ovaj odjeljak kao neprovjeren.",
