  "dest.groupTip.cloud": "Usluge namijenjene dokumentima i fotografijama. Ograničavaju velik broj zahtjeva, pa prva sigurnosna kopija i čišćenje traju dulje.",
  "dest.note.slower": "Radi, ali sporije. {name} ograničava velik broj zahtjeva, pa prva sigurnosna kopija i čišćenje ovdje traju puno dulje nego kod usluge pohrane.",
