  "dest.token.run": "Pokrenite ovo na računalu s preglednikom i prijavite se",
  "dest.token.tip": "BombVault radi na poslužitelju bez preglednika. rclone otvara prijavu na vašem računalu i potom ispisuje token, koji se upisuje u polje ispod. rclone za Windows, macOS i Linux dostupan je na rclone.org.",
  "dest.trustToken.run": "Prijavi se na računalu s rcloneom, a zatim zalijepi trust_token i cookies iz rclone config show u polja ispod",
  "dest.trustToken.tip": "iCloud Drive traži tvoju uobičajenu lozinku za Apple ID, ne lozinku za aplikacije, i dvofaktorski kôd koji može zatražiti samo rclone config. Apple tu prijavu prekida nakon 30 dana, a kopije na iCloud Drive ne uspijevaju dok se ponovno ne prijaviš i ne zalijepiš nove vrijednosti u {change}.",
