  "dest.route.s3": "S3 usluge koriste restic vlastiti S3 backend umjesto rclonea, što omogućuje primjenu klase pohrane i Object Locka.",
  "dest.route.rclone": "restic do ove usluge dolazi preko rclonea koji dolazi uz BombVault. Remote se zatim pojavljuje u rclone.conf u odjeljku „Postavke, Odredišta“.",
