  "dest.lock.s3": "Uključite verzioniranje i Object Lock za bucket. Stare verzije tada ostaju sačuvane čak i ako netko izbriše s ključem. BombVault to za {name} još ne može provjeriti.",
  "dest.lock.none": "{name} ne može odbiti brisanje. Tko uđe na vaš poslužitelj, ulazi i u ovaj repozitorij izvan lokacije. Protiv ransomwarea pomaže rest-server ili usluga pohrane s Object Lockom, na primjer kao drugo odredište.",
