  "dest.recovery.token": "{name} stalno obnavlja svoj pristup, pa token iz starije samostalne sigurnosne kopije može biti istekao. Tada se prijavite još jednom. Sam repozitorij nije pogođen.",
  "dest.recovery.ssh": "SSH ključ također se vraća uz samostalnu sigurnosnu kopiju. Na svježoj instalaciji bez nje novi ključ treba staviti na poslužitelj.",
