  "offsite.prune.title": "5 · Čišćenje izvan lokacije",
  "offsite.prune.info": "Ovaj korak samo javlja što se događa, ništa ne postavlja. Hoće li se ova kopija čistiti, određuju samo-dodavanje iz koraka 4 i vrijednosti zadržavanja u odjeljku „Postavke, Odredišta“. Želite li ipak očistiti kopiju sa samo-dodavanjem, pokrenite restic forget --prune na strani pohrane, bilo po vlastitom rasporedu bilo tako da nakratko podignete drugi REST poslužitelj bez samo-dodavanja, kroz njega očistite i opet ga ugasite.",
  "offsite.prune.stateFarSide": "Odavde ništa ne čisti ovu kopiju. Samo-dodavanje je uključeno, pa joj BombVault samo dodaje, a čišćenje je posao strane pohrane.",
