  "rcloneRemote.heading": "Dodaj SMB ili WebDAV odredište",
  "rcloneRemote.hint": "Povezuje se s Windows ili Samba dijeljenom mapom, ili s WebDAV poslužiteljem kao što je Nextcloud, bez montiranja na hostu. restic ne preporučuje držanje repozitorija na montiranoj CIFS dijeljenoj mapi, a ovaj put potpuno zaobilazi montiranje. Lozinka se predaje rcloneu, koji je sprema u vlastitom obliku, i nikad se ne čuva kao otvoreni tekst. NFS se ovdje ne nudi jer ga ne podržavaju ni restic ni rclone: za NFS montirajte izvoz u Unraidu i postavite putanju sigurnosne kopije prema njemu.",
