  "deferral.title": "Kad je aplikacija zauzeta",
  "deferral.hint": "Sigurnosna kopija zaustavlja spremnik, pa zakazana kopija može pričekati dok netko koristi aplikaciju i sama pokušati ponovno. Čeka kad Naredba prije sigurnosne kopije završi s kodom 75 ili kad provjera ispod pronađe da je aplikacija zauzeta; svaki drugi izlazni kod i dalje znači neuspjeh. Ostatak pokretanja u međuvremenu ide dalje, a kopija koja čeka dolazi na red kad se ne izvodi nijedna druga kopija. Napravi sigurnosnu kopiju sada uvijek se pokreće odmah.",
  "deferral.preset": "Provjera aktivnosti",
  "deferral.presetHint": "Prije zakazane sigurnosne kopije pita medijski poslužitelj gleda li netko nešto. Svaka sesija koja se reproducira, i svaka pauzirana, tjera kopiju da čeka. BombVault pita poslužitelj izravno kad može doći do spremnika, a inače preko curl ili wget unutar spremnika, što radi i za spremnike na br0 ili macvlan.",
  "deferral.presetNone": "Nijedna",
