  "deferral.failOpen": "Napravi kopiju kad poslužitelj ne odgovara",
  "deferral.failOpenHint": "Uključeno: ako se medijski poslužitelj ne može pitati, kopija se izvodi, a zapisnik to bilježi. Isključeno: kopija čeka i pokušava se ponovno, kao da netko gleda.",
  "deferral.net": "Čekaj dok spremnik šalje podatke",
  "deferral.netHint": "Za aplikaciju bez provjere aktivnosti, poput poslužitelja za igre ili programa za preuzimanje. Zakazana kopija čeka dok je spremnik pri bilo kojem mjerenju u zadnjih nekoliko minuta poslao više od granice, prema Dockerovim vlastitim brojačima. Spremnik na mreži domaćina nema ih i kopira se.",
  "deferral.netKiB": "Zauzet od (KiB/s)",
