  "dbdump.databasesLine": "Baze podataka: {names}",
  "dbdump.damagedBadge": "Oštećen",
  "dbdump.damagedHint": "Ovaj ispis nije prošao provjere i nije ga bilo moguće automatski ukloniti. Ne može se preuzeti ni uvesti. Izbrišite ga.",
  "dbdump.download": "Preuzmi",
