  "dbdump.importRefused.versionSameMajor": "Poslužitelj radi na verziji {server}, ispis dolazi iz {dump}. MySQL i MariaDB uvoze ispis samo u glavnu verziju iz koje potječe, pa za ovaj uvoz upotrijebite sliku s verzijom {dump}.",
