  "recovery.abTitle": "Uvoz iz dodatka Appdata.Backup",
  "recovery.abIntro": "Od arhiva koje je zapisao dodatak Appdata.Backup stvara točke vraćanja odgovarajućih kontejnera, svaku s datumom kad ju je dodatak napravio. Arhive se samo čitaju, nikad se ne mijenjaju ni brišu. Svaka se raspakira pokraj repozitorija, sigurnosno kopira, a raspakirana kopija se ponovno uklanja, pa tamo mora biti mjesta za najveću arhivu.",
