  "api.title": "API tokeni",
  "api.hint": "Tokeni za skripte, nadzorne ploče i kućnu automatizaciju. Token otvara API pod /api/v1 i ništa drugo. Vraćanja, brisanja i postavke ostaju u ovom web sučelju.",
  "api.addressLabel": "Adresa API-ja",
  "api.addressHint": "Šalji token kao Authorization: Bearer <token> ili u zaglavlju X-API-Key. Opis svih ruta nalazi se na /api/v1/openapi.json i ne treba token.",
  "api.viewDescription": "Otvori opis",
  "api.noPasswordWarning": "Lozinka za prijavu nije postavljena, pa je ovo web sučelje otvoreno svima na vašoj mreži, a tko ga može otvoriti može i stvoriti token.",
  "api.needsPasswordForHost": "Ova je stranica otvorena kao {host}. Bez lozinke za prijavu tokeni se mogu stvarati i zamjenjivati samo s IP adrese ili lokalnog imena poput tower ili tower.local. Postavite lozinku za prijavu ili otvorite BombVault preko njegove lokalne adrese.",
  "api.labelLabel": "Naziv tokena",
