  "anomaly.cardHint": "BombVault uspoređuje svaku sigurnosnu kopiju stavke s prethodnima i imenuje ono što odskače: puno više novih podataka nego inače, ponovno pisanje većine podataka, izvor koji se jako smanjio ili narastao, manji ispis baze podataka, kopiju koja odjednom traje puno dulje, ponovljene neuspjehe, provjeru vraćanja koja više ne prolazi i disk koji će se uskoro napuniti. Većini provjera najprije treba 10 kopija stavke. ZFS stavka provjerava se skup po skup podataka, pa se ispražnjeni podređeni skup vidi i u velikom stablu.",
